float movx = 0.;
float movy = 0.;

mat2 rot(float phi) {
  float ca=cos(phi);
  float sa=sin(phi);
  return mat2(ca,sa,-sa,ca);
}

float box(vec3 p, float s) {
  p=abs(p)-s;
  return max(p.x, max(p.y,p.z) );
}

float block(vec3 p) {
    float t=iTime*0.2;
    //
    vec3 p0 = p;
    p0.y -= -1. + ( sin(t*4.) * 1.4 );
    p0.xy *= rot(0.3);
    float d1 = box(p0,0.9);
    //
    vec3 p01 = p;
    p01.x -= 0.5;
    p01.y -= -1.2 + ( cos(t*7.) * 1.3 );
    p01.xy *= rot(-0.7);
    float d01 = box(p01,0.7);
    //
    vec3 p1 = p;
    p1.x += 0.;
    p1.y -= 1.1 + ( sin(t*3.) * 1.2 );
    p1.xz *= rot(0.6);
    p1.xy *= rot(-0.73);
    float d2 = box(p1,2.4);
    //
    float dq = min(d1,d01);
    return min(dq,d2);
}

float map(vec3 p) {
  float t=iTime*0.9;
  //
  float sss = 6.*sin(p.z/36.);
  float zzz = 3.*sin(p.z/32.);
  p.x += sss;
  p.y += zzz;
  //
  float dfx = 1. + movx * 0.023;
  float dfy = 1. + movy * 0.012;
  vec3 pr = vec3( 
      atan(p.x,p.y)*12., 
      length(vec2(p.x*dfx,p.y*dfy))-18., 
      p.z
  );
  //
  pr.z += 26.*sin(t)+ 14.;
  p = pr;
  //
  float dist=60.;
  p.z = (fract(p.z/dist-0.5)-0.5)*dist;
  //
  float s=19.;
  for(int i=0;i<6;i++) {
      p.xz *= rot(float(i) * 5.7);
      p.xz  = abs(p.xz);
      p.xz  -= s;
      s *= 0.6;
  }
  //
  return block(p);
}

vec3 moveXY(vec3 p) {
  movx =     sin(p.z * 0.018)*5.;
  movy = 10.+ cos(p.z * 0.023)*3.;
  //
  vec3   o    =  vec3(0.);
         o.x  += movx; 
         o.y  += movy;
  return o;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  float time = iTime * 2.0;
  vec2 p = (fragCoord.xy - iResolution.xy * 0.5) / iResolution.y;
  //
  vec3 ro   = vec3(0  , -12. ,-46.);
  vec3 cpos = vec3(0.0,   0. ,  0.);
  //
  float mov = mod(time, 120.)*26.;
  ro.z   += mov;
  cpos.z += mov; 
  //
  ro   +=moveXY(ro);
  cpos +=moveXY(cpos);
  //
  vec3 cz = normalize( cpos-ro );
  vec3 cx = normalize( cross(cz,vec3(0.,1.0,0.) ) );
  vec3 cy = normalize( cross(cz,cx) );
  //
  vec3 rd = normalize( cx*p.x + cy*p.y + cz*0.5);
  //
  vec3 pm=ro;
  float dd=0.;
  for(int i=0;i<64; ++i) {
      float d = map(pm);
      if ( (d<0.01) || (dd>156.) ) {
        break;
      }
      pm +=rd*d;
      dd+=d;
  }
  //
  float fog=1.-clamp(dd/158.,0.,1.);
  vec3 col=vec3(0);
  vec2 off=vec2(0.4,0);
  //
  vec3 n=normalize(map(pm)-vec3(map(pm-off.xyy), map(pm-off.yxy), map(pm-off.yyx)));
  vec3 l=normalize(vec3(-1.,-3.,-2.));
  col += max(0.0, dot(n,l) ) * fog*0.3 * vec3(0.3,0.4,.7);
  col += pow(.95-fog, 1.4) * vec3(1.,.5,.2) * 2.4 / length(vec2(p.x*2.2,p.y*2.2));
  col = pow( col, vec3(0.95) );
  //
  fragColor =  vec4(col, 1.0);
}
